using System;using System.IO;using System.Reflection;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Windows.Forms;using System.Web.Script.Serialization;
class PneumaticBranchProbe {
static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;static void Call(object h,string n){typeof(TrainerIntegrationHost).GetMethod(n,flags).Invoke(h,null);}static float F(IntPtr p,int o){byte[] b=new byte[4];Marshal.Copy(IntPtr.Add(p,o),b,0,4);return BitConverter.ToSingle(b,0);}
[STAThread]static int Main(string[] args){Application.EnableVisualStyles();var h=(TrainerIntegrationHost)Activator.CreateInstance(typeof(TrainerIntegrationHost),true);try{IntPtr handle=h.Handle;Call(h,"StartNative");((Timer)typeof(TrainerIntegrationHost).GetField("timer",flags).GetValue(h)).Stop();var mem=(Dictionary<string,IntPtr>)typeof(TrainerIntegrationHost).GetField("mem",flags).GetValue(h);var loc=mem["TLocParam"];var tc=new List<float>();foreach(int k in new int[]{2,3,4,5,6,2}){Marshal.WriteByte(loc,0x7e,(byte)k);for(int n=0;n<180;n++)Call(h,"PneumaticCycle");tc.Add(F(loc,13));}float[] expected={0,1.15f,1.85f,2.85f,3.9375f,0};for(int n=0;n<tc.Count;n++)if(Math.Abs(tc[n]-expected[n])>.12)throw new Exception("KVT target failed "+n+" actual="+tc[n]);Marshal.Copy(BitConverter.GetBytes(8f),0,IntPtr.Add(loc,0x9f),4);Marshal.WriteByte(loc,0x9a,0);Marshal.WriteByte(loc,0x9b,1);int cross=0;for(int n=1;n<=100;n++){Call(h,"PneumaticCycle");if(F(loc,0x9f)<=1.5f){cross=n;break;}}if(cross!=66)throw new Exception("EPK timing changed: "+cross);Marshal.WriteByte(loc,0x9a,1);Marshal.WriteByte(loc,0x9b,0);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,args[0]+".json"),new JavaScriptSerializer().Serialize(new{passed=true,epk_crossing_calls=cross,epk_host_seconds=cross*.1,kvt_codes=new int[]{2,3,4,5,6,2},kvt_tc_bar=tc,scope="Native branch pressure and frequency; not complete EPK trip safety validation"}));Console.WriteLine("PASS EPK66; KVT="+string.Join(",",tc));return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}finally{h.Close();h.Dispose();}}
}


